// AlbumCreateRequest The creation body of one directory album
// (albums-as-sources): the title, the existing directory the
// album references in place, the audience the album starts
// with, and the two dialog switches of the create-time
// autonomy -- the deletability switch and the creator's
// timeline exclusion. No type field exists -- this endpoint IS
// directory creation, the only creatable album type. No
// description field either: it died whole (the 2026-11-08 owner
// evaluation -- real-world fill rate near zero, the context
// already carried by title/date-range+count/place/cover), and
// the property patch carries no field that could set one.
type AlbumCreateRequest struct {
	// AllowAppDeletion The owner's deletability switch, carried from the
	// creation dialog: whether the album's photos may be
	// deleted through the application (the trash move of the
	// source file). On by default; the dialog renders the
	// switch only where the source is writable (the
	// completion row's `writable` fact), and on a read-only
	// source the stored value governs nothing -- the derived
	// `deletable` face stays false whatever it says. Editable
	// later through the property patch.
	AllowAppDeletion *bool `json:"allowAppDeletion,omitempty"`

	// Audience The accounts the album starts being visible to: the
	// initial `album_shares` set, empty (or absent) meaning
	// "only me". Entries that cannot be granted -- an unknown
	// or disabled account, or the caller's own id -- are
	// skipped and reported in the response's `skipped` list,
	// never errors.
	Audience *[]openapi_types.UUID `json:"audience,omitempty"`

	// InTimeline The creator's timeline preference, carried from the
	// creation dialog: `false` keeps the album out of the
	// CREATOR's aggregated timeline from birth -- the same
	// per-user switch `PUT /albums/{albumId}/timeline-preference`
	// writes, landed in the creation itself (a per-user
	// preference, not an album fact: it needs no photos to
	// exist, so the creation is exactly the right moment).
	// Absent or true feeds the timeline (the default -- no
	// preference row is written). The exclusion is the
	// creator's own: the audience members' feeds are governed
	// by their own preference rows, never by this field.
	InTimeline *bool `json:"inTimeline,omitempty"`

	// RootPath The source directory: an existing absolute path the
	// server validates against the path matrix (existence,
	// directory-ness, readability, symlink resolution, the
	// managed tree) before creating anything. The album row
	// stores the RESOLVED absolute path -- symlink segments
	// evaluated -- so a later symlink swap cannot repoint the
	// album. After the matrix passes, the server probes the
	// directory's writability once and records the fact; a
	// read-only directory is a valid source, never a refusal.
	RootPath string `json:"rootPath"`

	// Title The album's display title, trimmed server-side; it must
	// span 1-64 Unicode characters after the trim (the count
	// is over runes, so multi-byte titles stay within the
	// bound at the same length).
	Title string `json:"title"`
}

// AlbumCreateResponse The creation answer: the fresh directory album's wall card
// (the summary exactly as `GET /albums` lists it) plus the
// honest audience report -- the requested ids that did not
// become audience, each with its reason -- and the creation
// probe's `sourceWritable` fact. The card's companions are the
// creation-time constants: `callerRole` `owner`, `isShared`
// true exactly when the audience landed a row, an empty
// `coverAssetIds`, `itemCount` 0, `photoCount` 0.
type AlbumCreateResponse struct {
	// CallerRole The caller's relation to this album: `owner` items belong
	// to the caller's own group on the wire, `viewer` items to
	// the shared group. The client renders ONE wall list and
	// keys each card's face off this discriminator (the
	// read-only mark is the member's, the shared state the
	// owner's).
	CallerRole AlbumCreateResponseCallerRole `json:"callerRole"`

	// CoverAssetIds The collage source of the wall card, in render order: the
	// frames of the album's cover. A cover holds four frames
	// (the album card's 2x2 collage) or six (the memory band's
	// 3-across 2-down strip), and the server answers the group
	// the card draws -- the card is the first thing rendered
	// and cannot see the collection, so the automatic group is
	// computed here, never by the client.
	//
	// The owner's pinned set wins: when the owner picked a full
	// set, these are its frames in pick order, exactly as
	// written (the server never re-sorts a pin). An album
	// without pins renders the automatic group: a weekly
	// rotation, re-sampled per ISO week from the whole live
	// collection (never the newest frames and never a random
	// order), frozen for the week so an upload mid-week cannot
	// move a frame, and never rotating at all while the album
	// holds fewer than twice the frame count -- such an album
	// keeps one stable sample of its own. A pinned frame that
	// is no longer visible to the caller (moved out, trashed,
	// archived) is filled silently from the caller's visible
	// pool; a fully dead pin falls back to the automatic group.
	//
	// The order is the render order and the length is at most
	// the card's frame count: a collection with fewer members
	// than frames answers the frames it has (one fills, two
	// split, three lay one large beside two small), and an
	// album with no members answers an empty array (the card's
	// empty cover, no placeholder photo).
	CoverAssetIds []openapi_types.UUID `json:"coverAssetIds"`

	// Id Identifier of the album.
	Id openapi_types.UUID `json:"id"`

	// InTimeline The caller's timeline preference of this album: whether
	// it feeds their aggregated timeline. Present exactly on
	// the excludable cards -- the own `directory` items and
	// every shared item; the own `memory` items omit it
	// (they never feed the caller's own timeline, so there is
	// nothing to exclude), and the pinned `sync` card omits it
	// too (the core stream is never excludable). The value is
	// the preference row's switch, true when no row exists
	// (the default).
	InTimeline *bool `json:"inTimeline,omitempty"`

	// IsShared True when the album carries at least one `album_shares`
	// row -- someone besides the owner can see it. Always true
	// on shared-group items by construction.
	IsShared bool `json:"isShared"`

	// ItemCount The album's member count: trashed and Live Photo component
	// rows never count, while an archived member does -- an
	// album is a reference container that keeps its archived
	// members (a memory, a family-flow surface, drops them).
	// The members of every media kind count here -- this is
	// the collection's own size, the number the cover pool and
	// the removal's arithmetic consult.
	ItemCount int `json:"itemCount"`

	// Owner The owner attribution of a shared item: the account that
	// owns the album. Present exactly when `callerRole` is
	// `viewer`; own items omit it (the owner is the caller).
	Owner *AlbumOwnerRef `json:"owner,omitempty"`

	// PhotoCount The album's PHOTO count: the same member predicate
	// narrowed to `kind: image` members. The
	// interface's count idiom beside the image glyph reads
	// this field (it says "12 photos", so it counts photos);
	// a video is a member but never a photo, and the wall
	// marks it with its own glyph instead. Equal to
	// `itemCount` for an album holding no videos.
	PhotoCount int `json:"photoCount"`

	// Skipped The requested audience ids that stayed ungranted:
	// the album's own owner and every id that names no
	// usable account. Empty when the whole audience
	// landed.
	Skipped []AlbumAudienceSkip `json:"skipped"`

	// SourceWritable The creation-time write probe's fact of the album
	// this response just created: `true` when the probe
	// file landed, read back and removed cleanly; `false`
	// for a readable but read-only source. The creation
	// SUCCEEDED either way -- a read-only directory is a
	// legitimate album -- and `false` is the honest
	// feedback the dialog renders (photos of this
	// directory cannot be deleted through the
	// application).
	SourceWritable bool `json:"sourceWritable"`

	// Title The album's display title.
	Title string `json:"title"`

	// Type The album's type. `memory` albums are reference sets
	// curated by their owner -- photos live in the albums they
	// were ingested through, a memory holds references to
	// them; `directory` albums mirror a filesystem path. The
	// one `sync` card, when present, is the caller's own
	// default album pinned first (never another account's):
	// its `title` is the internal system label ('Sync') and
	// clients render the localized display name instead (en
	// "My photos", zh-Hans "我的照片").
	Type AlbumCreateResponseType `json:"type"`

	// UpdatedAt When the album row last changed (RFC 3339 UTC).
	UpdatedAt time.Time `json:"updatedAt"`
}

// AlbumCreateResponseCallerRole The caller's relation to this album: `owner` items belong
// to the caller's own group on the wire, `viewer` items to
