// `LIVE_PHOTO_MOTION_ABSORBED`: the Live Photo's motion bytes
// already existed as a live standalone video of this owner;
// that row became the pair's motion (`assetId` names it) and
// no longer lists as its own asset. Carried on a 201
// `created` answer.
//
// `LIVE_PHOTO_MOTION_ALREADY_STORED`: the uploaded bytes
// already play as a Live Photo's motion, so the returned
// row is that hidden component (`assetId` names it) and does
// not list on its own. Carried on a 200 `duplicate` answer:
// the content genuinely exists, so the state stays
// `duplicate` -- there is nothing for the user to fix.
type AssetNoticeCode string

// AssetPatch The partial edit of one asset: every field is optional, at
// least one must be present (a body that carries none -- null
// values count as absent -- is a client bug and answers 400),
// and only the fields the request carries update; the rest keep
// their values. Every field is owner-level asset state, so a
// patch that actually changes one of them publishes a single
// `asset.updated` event; a patch that repeats the stored values
// is the idempotent no-op and publishes nothing.
type AssetPatch struct {
	// Description The owner's free-text description of the asset, the text
	// the detail panel renders. The value replaces the stored
	// text wholesale (an empty string clears it). At most
	// 10,000 Unicode characters -- the count is over runes, so
	// a text of multi-byte characters stays within the bound at
	// the same length.
	Description *string `json:"description,omitempty"`

	// IsArchived The owner-level archive switch: `true` keeps the asset out
	// of every family flow until it is unarchived; `false`
	// returns it. An album keeps its archived members, so the
	// album surface is unaffected either way. The same switch
	// the batch `hide` / `unhide` actions flip.
	IsArchived *bool `json:"isArchived,omitempty"`

	// Latitude The manual location edit's latitude, in degrees
	// (-90..90). It rides with `longitude` (the pair is the
	// location; one half alone answers 400
	// `VALIDATION_FAILED`). Writing the pair replaces the
	// asset's location: the info panel renders these
	// coordinates and the resolved place follows the pin. The
	// camera-recorded GPS in `exif` keeps the file's own
	// reading and is not touched.
	//
	//
	// Examples: 36.0671
	Latitude *float64 `json:"latitude,omitempty"`

	// Longitude The manual location edit's longitude, in degrees
	// (-180..180). It rides with `latitude` (see there for the
	// pair's semantics).
	//
	//
	// Examples: 120.3826
	Longitude *float64 `json:"longitude,omitempty"`

	// TakenAt The owner's manual capture-time edit: the value replaces
	// the stored instant wholesale. The timestamp MUST carry a
	// UTC offset (RFC 3339's `Z` or `+hh:mm` designator) -- the
	// offset is the capture zone the info panel displays beside
	// the time, so a zone-less value is ambiguous and answers
	// 400 `VALIDATION_FAILED`. The same value decides where the
	// photo sits on the timeline (the instant) and which offset
	// renders beside it (the offset).
	//
	//
	// Examples: 2026-08-12T18:42:00+08:00
	TakenAt *time.Time `json:"takenAt,omitempty"`
}

// AssetPlaceRef The asset detail's `place` face: the resolved city as the
// info panel renders it -- the deep link's key and the
// display name, nothing more (the place listing's counts and
// covers are the `GET /places` face's own).
type AssetPlaceRef struct {
	// Name The display name at the request's locale: the
	// `place_names` row of that locale when the place data
	// carries one, the GeoNames canonical (English or
	// romanized) name otherwise.
	//
	//
	// Examples: Paris, 巴黎
	Name string `json:"name"`

	// PlaceId The GeoNames geonameid of the place -- the `places` row's
	// primary key and the `assets.place_id` foreign key, the
	// same identifier the place-filtered browse filters on.
	//
	//
	// Examples: 2988507
	PlaceId int32 `json:"placeId"`
}

// AssetResponse One stored asset as the upload and idempotency endpoints return
// it. `state` discriminates the upload outcome: `created` (201, a
// new asset), `duplicate` (200, an identical live asset already
// existed), `trashed` (200, an identical asset sits in the trash;
// the body carries that asset so the client can offer restore or
// save-as-new). The idempotency lookup mirrors the same states:
// it reports what a re-upload of the content would yield, so
// `created` never appears there.
//
// `notices` is absent or empty unless something needs telling:
// a Live Photo whose motion bytes were reused as an existing
// standalone video's row, or a standalone video whose bytes
// already play as some Live Photo's motion (the returned row is
// then that hidden component, still a `duplicate`). A client
// that ignores it leaves the user with a video that silently
// stopped listing on its own, so the obligation to surface each
// notice is part of the contract, not a presentation choice.
type AssetResponse struct {
	// Checksum SHA-256 digest of the file bytes, lowercase hex. The
	// owner-scoped idempotency key of the upload.
	Checksum string `json:"checksum"`

	// CreatedAt When the asset record was created (RFC 3339 UTC).
	CreatedAt time.Time `json:"createdAt"`

	// FileSize Size of the stored file in bytes.
	FileSize int64 `json:"fileSize"`

	// Id UUIDv7 identifier of the asset.
	Id openapi_types.UUID `json:"id"`

	// IsTrashed True when the asset sits in the trash; `state: trashed`
	// responses carry it as true so clients can offer the
	// restore or save-as-new decision.
	IsTrashed bool `json:"isTrashed"`

	// Kind Media family of the asset. A Live Photo is an `image` whose
	// video component is stored as a linked `video` row that
	// never appears in the timeline.
	Kind AssetResponseKind `json:"kind"`

	// MimeType Canonical content type of the stored format, for example
	// `image/jpeg` or `video/quicktime`.
	MimeType string `json:"mimeType"`

	// Notices What the client must tell the user about this upload.
	// Absent or empty when there is nothing to say; the array is
	// informational, never a failure list. Present on a 201
	// `created` answer today (a Live Photo motion absorbed into
	// an existing video); the client surfaces each entry to the
	// user without blocking the upload.
	Notices *[]AssetNotice `json:"notices,omitempty"`

	// OriginalFilename The file name the asset was uploaded with: the client-side
	// `fileName` of the photo (the component video keeps its own
	// file part name).
	OriginalFilename string `json:"originalFilename"`

	// OwnerId UUIDv7 identifier of the owning account.
	OwnerId openapi_types.UUID `json:"ownerId"`

	// State The upload outcome: `created` (201), `duplicate` (200, an
	// identical live asset) or `trashed` (200, an identical asset
	// in the trash).
	State AssetResponseState `json:"state"`

	// TakenAt Capture time (RFC 3339). Seeded from `deviceCreatedAt` (or
	// the upload time when absent) and refined from EXIF by the
	// metadata pipeline; responses render the best value the
	// server has at answer time.
	TakenAt time.Time `json:"takenAt"`
}

